import type * as THREE from 'three';
import type { QualityPreset, ResolvedQuality } from '../../config/quality.ts';

export interface RealmLighting {
  /** Equirectangular HDR used for image-based lighting and reflections (PMREM-filtered by the scene). */
  environment: THREE.Texture;
  /** True when `environment` is already a PMREM texture (generated by the realm itself). */
  prefiltered?: boolean;
  envIntensity: number;
  /** Radians around Y; must match any photo backdrop rotation so reflections line up with the photo. */
  envRotation: number;
  sunDir: THREE.Vector3;
  sunColor: number;
  sunIntensity: number;
  /** Fill from the sky/ground. Photo realms rely on the HDR instead and set this to 0. */
  hemiIntensity: number;
  exposure: number;
  fog: { color: number; density: number } | null;
  bloom: { strength: number; threshold: number };
  grade: { saturation: number; contrast: number; tint: number; vignette: number };
  shadowOpacity?: number;
  /** Optional back light that outlines pieces against dark backgrounds. */
  rim?: { dir: THREE.Vector3; color: number; intensity: number };
}

export interface Realm {
  readonly group: THREE.Group;
  readonly lighting: RealmLighting;
  /** 'pedestal' keeps the board's own plinth; 'none' when the realm supplies a table or stage. */
  readonly boardStand: 'pedestal' | 'none';
  /** Camera far plane this realm needs (photo backdrops are large). */
  readonly far: number;
  /** Preferred seat camera angle from vertical (radians) on landscape screens; lower = more horizon. */
  readonly seatPolar?: number;
  /** Camera angle for the slow menu orbit (lower shows more of the surroundings). */
  readonly menuPolar?: number;
  update(dt: number, time: number): void;
  /** Called when a capture lands (crowd cheer, camera flashes, etc.). */
  onImpact?(at: THREE.Vector3): void;
  dispose(): void;
}

export interface RealmContext {
  renderer: THREE.WebGLRenderer;
  quality: QualityPreset;
  qualityName: ResolvedQuality;
}

export type RealmFactory = (ctx: RealmContext) => Promise<Realm>;
